@extends('layouts.portal')
@section('content')
<div x-data="misNivelaciones()" x-init="cargar()" x-cloak><div class="mb-6"><h2 class="text-xl font-bold text-gray-900">Examen de nivelación</h2><p class="text-sm text-gray-500">Inscríbase al examen disponible o consulte su resultado y elija el horario recomendado.</p></div><div x-show="error" class="mb-4 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700" x-text="error"></div><section x-show="ofertas.length" class="mb-7"><h3 class="mb-3 font-semibold text-gray-800">Exámenes disponibles</h3><div class="grid gap-3 md:grid-cols-2"><template x-for="o in ofertas" :key="o.id"><button @click="reservar(o)" class="rounded-xl border border-brand-200 bg-white p-4 text-left shadow-sm hover:bg-brand-50"><p class="font-semibold" x-text="o.nivel"></p><p class="text-sm text-gray-600" x-text="o.horario+' · '+o.modalidad"></p><p class="text-xs text-gray-500" x-text="o.docente"></p><p class="mt-2 text-sm font-medium text-brand-700">Inscribirme al examen</p></button></template></div></section><h3 class="mb-3 font-semibold text-gray-800">Mis resultados</h3><template x-for="e in evaluaciones" :key="e.id"><div class="mb-4 rounded-xl border border-gray-200 bg-white p-5 shadow-sm"><div class="flex justify-between gap-3"><div><p class="font-semibold" x-text="e.codigo"></p><p class="text-sm text-gray-500" x-text="'Nota: '+e.nota_obtenida"></p></div><span class="badge" :class="e.estado==='aprobada'?'badge-success':e.estado==='rechazada'?'badge-danger':'badge-neutral'" x-text="e.estado"></span></div><template x-if="e.estado==='aprobada'"><div class="mt-4"><p class="text-sm">Nivel acreditado: <strong x-text="e.nivel_acreditado?.nombre"></strong></p><p class="text-sm">Nivel recomendado: <strong x-text="e.nivel_recomendado?.nombre"></strong></p><div class="mt-3 space-y-2"><template x-for="o in e.ofertas_recomendadas" :key="o.id"><button @click="reservar(o)" class="w-full rounded-lg border border-brand-200 p-3 text-left hover:bg-brand-50"><span class="font-medium" x-text="o.horario?.nombre+' · '+o.modalidad?.nombre"></span><span class="block text-xs text-gray-500" x-text="o.docente?.nombre+' '+o.docente?.apellido"></span></button></template><p x-show="e.ofertas_recomendadas.length===0" class="text-sm text-amber-700">No hay ofertas abiertas con cupo para el nivel recomendado.</p></div></div></template></div></template><p x-show="!loading&&evaluaciones.length===0" class="rounded-xl bg-white p-6 text-center text-gray-500">Aún no tiene resultados de nivelación.</p></div>
@endsection
@section('scripts')<script>function misNivelaciones(){return{evaluaciones:[],ofertas:[],loading:false,error:'',async cargar(){this.loading=true;try{const h={headers:{Authorization:`Bearer ${localStorage.getItem('estudiante_token')}`}};const[r,o]=await Promise.all([window.axios.get('/api/v1/estudiantes/mis-nivelaciones',h),window.axios.get('/api/v1/estudiantes/ofertas-nivelacion',h)]);this.evaluaciones=r.data.data||[];this.ofertas=o.data.data||[]}catch(e){this.error=window.extractError(e,'No fue posible cargar las nivelaciones')}finally{this.loading=false}},async reservar(o){try{const{data}=await window.axios.post('/api/v1/estudiantes/reservar-matricula',{oferta_academica_id:o.id,plan_estudio_id:o.plan_estudio_id},{headers:{Authorization:`Bearer ${localStorage.getItem('estudiante_token')}`}});if(data.resultado==='A')window.location.href=`/estudiante/pagos?nuevo_pago=1&matricula_id=${data.data.matricula_id}`}catch(e){this.error=window.extractError(e,'No fue posible reservar esta oferta')}}}}</script>@endsection
